with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MD_SEQ_NO))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as MEMBER_REFERENCE
        , cast(null as varchar) as CONDITION_CODE
        , MD_OBESITY as DISCLOSED_INDICATOR
        , cast(null as varchar) as CONDITION_NAME
        , cast(null as varchar) as LAST_TREATMENT_DATE
        , cast(null as varchar) as DATE_OF_MARRIAGE
        , cast(null as varchar) as UNDERWRITING_LOADING_PERCENTAGE
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(MD_SEQ_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MEMBER_NO))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as MEMBER_REFERENCE
        , cast(null as varchar) as CONDITION_CODE
        , PREGNANT_YN as DISCLOSED_INDICATOR
        , PRIOR_4YR_ILLNESS as CONDITION_NAME
        , PRIOR_4YR_TREAT_DATE as LAST_TREATMENT_DATE
        , cast(null as varchar) as DATE_OF_MARRIAGE
        , cast(null as varchar) as UNDERWRITING_LOADING_PERCENTAGE
        , 'BJAZ_EC_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ec_mem_dtls_extn') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MEMBER_NO))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as MEMBER_REFERENCE
        , cast(null as varchar) as CONDITION_CODE
        , HYPERLIPIDE_FLAG as DISCLOSED_INDICATOR
        , DIABETES_TYPE as CONDITION_NAME
        , cast(null as varchar) as LAST_TREATMENT_DATE
        , cast(null as varchar) as DATE_OF_MARRIAGE
        , OTHER_RISK_LOAD as UNDERWRITING_LOADING_PERCENTAGE
        , 'BJAZ_HCF_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcf_member_dtls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__CONTRACT_ID_MEMBER_ID))) as HUB_RISK_OBJECT_HK
        , coalesce(nullif(trim(MEMBER_ID), ''), '') as MEMBER_REFERENCE
        , 'DECLARED_OTHER' as CONDITION_CODE
        , GMC_IHD as DISCLOSED_INDICATOR
        , DISEASE_DTLS as CONDITION_NAME
        , cast(null as varchar) as LAST_TREATMENT_DATE
        , cast(null as varchar) as DATE_OF_MARRIAGE
        , cast(null as varchar) as UNDERWRITING_LOADING_PERCENTAGE
        , 'BJAZ_HM_MEMBER_HLTH_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_hlth_dtls') }}
    where (nullif('MEMBER:' || coalesce(nullif(trim(CONTRACT_ID),''),'') || '#' || coalesce(nullif(trim(MEMBER_ID),''),''), 'MEMBER:#')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        MEMBER_REFERENCE,
        CONDITION_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DISCLOSED_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISCLOSED_INDICATOR end)) as DISCLOSED_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CONDITION_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONDITION_NAME end)) as CONDITION_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LAST_TREATMENT_DATE end) as LAST_TREATMENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DATE_OF_MARRIAGE end) as DATE_OF_MARRIAGE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then UNDERWRITING_LOADING_PERCENTAGE end) as UNDERWRITING_LOADING_PERCENTAGE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK, MEMBER_REFERENCE, CONDITION_CODE
),

hashed as (
    select
        *,
        case when MEMBER_REFERENCE is not null or CONDITION_CODE is not null or DISCLOSED_INDICATOR is not null or CONDITION_NAME is not null or LAST_TREATMENT_DATE is not null or DATE_OF_MARRIAGE is not null or UNDERWRITING_LOADING_PERCENTAGE is not null
                     then md5(upper(coalesce(cast(MEMBER_REFERENCE as varchar), '') || '|' || coalesce(cast(CONDITION_CODE as varchar), '') || '|' || coalesce(cast(DISCLOSED_INDICATOR as varchar), '') || '|' || coalesce(cast(CONDITION_NAME as varchar), '') || '|' || coalesce(cast(LAST_TREATMENT_DATE as varchar), '') || '|' || coalesce(cast(DATE_OF_MARRIAGE as varchar), '') || '|' || coalesce(cast(UNDERWRITING_LOADING_PERCENTAGE as varchar), '')))
                end as SAT_RISK_HEALTH_MEMBER_MEDICAL_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_HEALTH_MEMBER_MEDICAL_HASHDIFF is not null
